#!/usr/bin/env python3
"""Writes docs/CLI.md from the command table of src/cli_help.rs (run from the repository root); with an argument the page goes to that file."""
import re, sys
src = open("src/cli_help.rs").read()
body = src[src.index("const COMMANDS"):src.index("fn find")]
rows = re.findall(r'\(\s*"([^"]+)",\s*"((?:[^"\\]|\\.)*)",\s*"((?:[^"\\]|\\.)*)",\s*"((?:[^"\\]|\\.)*)",?\s*\)', body, re.S)
un = lambda t: t.replace("\\n", "\n").replace('\\"', '"').replace("\\\\", "\\")
out = ["# Command line: `yerux`\n",
       "<!-- generated by scripts/gen_cli_doc.py from the command table in src/cli_help.rs: `yerux --help`, `yerux help COMMAND` and `yerux COMMAND --help` print the same words (tests/cli_help.sh checks that every command is listed here) -->\n",
       "`yerux COMMAND [ARGS]`. `yerux --help` lists the commands on stdout (exit 0), `yerux help COMMAND` and `yerux COMMAND --help` describe one. A wrong command line prints a usage to stderr and exits 2; a failed check, test or program exits 1 (or the program's own status for `run`). Flags after `--` belong to the program (`yerux run prog.yx -- --help`).\n",
       "## Commands\n", "| Command | What it does |\n|---|---|"]
for n, sm, us, de in rows:
    out.append("| [`%s`](#%s) | %s |" % (n, n, un(sm)))
for n, sm, us, de in rows:
    sm, us, de = un(sm), un(us), un(de)
    out.append("\n## `%s`\n\n%s.\n\n```\n%s\n```\n" % (n, sm[0].upper() + sm[1:], us.replace("usage: ", "")))
    if de:
        out.append(de + "\n")
out.append("""
## Environment

| Variable | Effect |
|---|---|
| `YERUX_CC` | the C compiler of the C backend (otherwise the first of `cc`, `gcc`, `clang` that runs; none found: the native backend) |
| `YERUX_LOCS`, `YERUX_BACKTRACE` | keep source locations / a backtrace in panic messages of C builds |
| `YERUX_LSP_DEBOUNCE_MS` | typing pause before `yerux lsp` publishes diagnostics (default 150) |

`yerux --selfhost COMMAND ...` runs the self-hosted front end ([SELFHOST.md](SELFHOST.md)).

## Exit status

| Code | Meaning |
|---|---|
| 0 | success (for `run`: the program's own status) |
| 1 | diagnostics, failed tests, unformatted files under `fmt --check`, or an error reading the project |
| 2 | a bad command line (unknown command or option, missing argument, unreadable path) |
| 101 | a Yerux program panicked |
""")
open(sys.argv[1] if len(sys.argv) > 1 else "docs/CLI.md", "w").write("\n".join(out))
